import React, { useState } from 'react';
import { BrowserRouter as Router, Route, Routes, useNavigate } from 'react-router-dom';
import './App.css';
import './index.css';

// Login Component
function Login() {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const navigate = useNavigate();

  const handleSubmit = (e) => {
    e.preventDefault();
    if (username && password) {
      // Redirect to form page on successful login
      navigate('/form');
    } else {
      setError('Please fill out both fields.');
    }
  };

  return (

    <div className="login-container">
      <h2>Login</h2>
      <form onSubmit={handleSubmit}>
        <div>
          <label>Username</label>
          <input 
            type="text" 
            value={username} 
            onChange={(e) => setUsername(e.target.value)} 
            required
          />
        </div>
        <div>
          <label>Password</label>
          <input 
            type="password" 
            value={password} 
            onChange={(e) => setPassword(e.target.value)} 
            required
          />
        </div>
        {error && <p style={{ color: 'red' }}>{error}</p>}
        <button type="submit">Login</button>
      </form>
    </div>
  );
}

// Form Component
function FormPage() {
  const [fullName, setFullName] = useState('');
  const [dob, setDob] = useState('');
  const [qualification, setQualification] = useState('');
  const [comments, setComments] = useState('');
  const [otherQualification, setOtherQualification] = useState('');
  const [error, setError] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!fullName || !dob || !qualification || !comments) {
      setError('All fields are required!');
      return;
    }
    // Insert data into the database
    // Here you can add the API call to submit the data to the backend

    console.log({
      fullName,
      dob,
      qualification,
      comments,
      otherQualification,
    });

    // Reset the form after submission
    setFullName('');
    setDob('');
    setQualification('');
    setComments('');
    setOtherQualification('');
    setError('');
  };

  return (
    <div className="form-container">
      <h2>Fill Form</h2>
      <form onSubmit={handleSubmit}>
        <div>
          <label>Full Name</label>
          <input 
            type="text" 
            value={fullName} 
            onChange={(e) => setFullName(e.target.value)} 
            required
          />
        </div>
        <div>
          <label>Date of Birth</label>
          <input 
            type="date" 
            value={dob} 
            onChange={(e) => setDob(e.target.value)} 
            required
          />
        </div>
        <div>
          <label>Qualification</label>
          <select 
            value={qualification} 
            onChange={(e) => setQualification(e.target.value)} 
            required
          >
            <option value="">Select</option>
            <option value="MCA">MCA</option>
            <option value="BCA">BCA</option>
            <option value="Others">Others</option>
          </select>
        </div>
        {qualification === 'Others' && (
          <div>
            <label>Other Qualification</label>
            <input 
              type="text" 
              value={otherQualification} 
              onChange={(e) => setOtherQualification(e.target.value)} 
            />
          </div>
        )}
        <div>
          <label>Message/Comments</label>
          <textarea 
            value={comments} 
            onChange={(e) => setComments(e.target.value.replace(/[^a-zA-Z\s]/g, ''))} 
            required
          />
        </div>
        {error && <p style={{ color: 'red' }}>{error}</p>}
        <button type="submit">Submit</button>
      </form>
    </div>
  );
}

// Data Table Component
function DataTable() {
  // You would retrieve the data from the backend API
  const [data, setData] = useState([
    { fullName: 'John Doe', dob: '1990-01-01', qualification: 'MCA', comments: 'Great!' },
    { fullName: 'Jane Smith', dob: '1992-05-12', qualification: 'BCA', comments: 'Good.' },
  ]);

  return (
    <div className="data-table">
      <h2>Submitted Data</h2>
      <table>
        <thead>
          <tr>
            <th>Full Name</th>
            <th>Date of Birth</th>
            <th>Qualification</th>
            <th>Comments</th>
          </tr>
        </thead>
        <tbody>
          {data.reverse().map((row, index) => (
            <tr key={index}>
              <td>{row.fullName}</td>
              <td>{row.dob}</td>
              <td>{row.qualification}</td>
              <td>{row.comments}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

function App() {
  return (
    <Router>
      <div className="App">
        <Routes>
          <Route path="/" element={<Login />} />
          <Route path="/form" element={<FormPage />} />
          <Route path="/data" element={<DataTable />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
